def resolve_session_dir(session_id: str) -> Path:
    """Find a session directory, checking root and all subfolders of OUTPUT_DIR.
    Falls back to root path if not found (caller handles non-existence)."""
    candidate = OUTPUT_DIR / session_id
    if candidate.is_dir():
        return candidate
    # Check one level of subdirectories (folder/session_*)
    for subfolder in OUTPUT_DIR.iterdir():
        if subfolder.is_dir() and not subfolder.name.startswith("session_"):
            candidate = subfolder / session_id
            if candidate.is_dir():
                return candidate
    return OUTPUT_DIR / session_id  # fallback


# ==================================================================================
# ALLOWED FOLDERS - restrict file browsing and local file access to these directories
# ==================================================================================
# Configured via ALLOWED_FOLDERS in .env (semicolon-separated paths).
# The output directory is always included automatically.
# Example .env:  ALLOWED_FOLDERS=D:\HCP_Aging;C:\Data\BIDS_Study
ALLOWED_FOLDERS: List[Path] = [OUTPUT_DIR.resolve()]

_env_folders = os.environ.get("ALLOWED_FOLDERS", "").strip()
if _env_folders:
    for _folder in _env_folders.split(";"):
        _folder = _folder.strip()
        if _folder:
            _p = Path(_folder).resolve()
            if _p not in ALLOWED_FOLDERS:
                ALLOWED_FOLDERS.append(_p)
                logging.info(f"Allowed folder (from .env): {_p}")

if len(ALLOWED_FOLDERS) == 1:
    logging.warning(
        "No ALLOWED_FOLDERS configured in .env. Only the output directory is browsable. "
        "Set ALLOWED_FOLDERS in .env to allow access to data directories."
    )


def is_path_allowed(file_path: str) -> bool:
    """Check if a file path falls within one of the allowed folders."""
    try:
        resolved = Path(file_path).resolve()
        for allowed in ALLOWED_FOLDERS:
            try:
                resolved.relative_to(allowed)
                return True
            except ValueError:
                continue
        return False
    except (OSError, ValueError):
        return False


@app.get("/allowed_folders")
async def get_allowed_folders():
    """Return the list of allowed folders for browsing."""
    return {
        "folders": [
            {"path": str(f), "exists": f.exists()}
            for f in ALLOWED_FOLDERS
        ]
    }


@app.post("/allowed_folders")
async def add_allowed_folder(folder_path: str = Form(...)):
    """Add a folder to the allowed list (runtime only, not persisted)."""
    p = Path(folder_path).resolve()
    if not p.exists():
        raise HTTPException(status_code=404, detail=f"Folder not found: {folder_path}")
    if not p.is_dir():
        raise HTTPException(status_code=400, detail=f"Path is not a directory: {folder_path}")
    if p not in ALLOWED_FOLDERS:
        ALLOWED_FOLDERS.append(p)
        logging.info(f"Added allowed folder: {p}")
    return {
        "message": f"Added allowed folder: {p}",
        "folders": [{"path": str(f), "exists": f.exists()} for f in ALLOWED_FOLDERS]
    }


@app.delete("/allowed_folders")
async def remove_allowed_folder(folder_path: str = Query(...)):
    """Remove a folder from the allowed list."""
    p = Path(folder_path).resolve()
    if p == OUTPUT_DIR.resolve():
        raise HTTPException(status_code=400, detail="Cannot remove the output directory from allowed folders")
    ALLOWED_FOLDERS[:] = [f for f in ALLOWED_FOLDERS if f != p]
    logging.info(f"Removed allowed folder: {p}")
    return {
        "message": f"Removed allowed folder: {p}",
        "folders": [{"path": str(f), "exists": f.exists()} for f in ALLOWED_FOLDERS]
    }

