def _ensure_viewer_available() -> None:
    """Ensure the interactive viewer prerequisites are met."""
    if not PIL_AVAILABLE:
        raise HTTPException(
            status_code=503,
            detail="Interactive viewer requires Pillow. Install with 'pip install pillow'."
        )


def _resolve_output_path(filename: str) -> Path:
    """Resolve a filename inside the output directory safely."""
    if not filename:
        raise HTTPException(status_code=400, detail="Filename is required.")

    # Check OUTPUT_DIR first, then VIEWER_CACHE_DIR
    candidate = (OUTPUT_DIR / filename).resolve()
    if not candidate.exists() or not candidate.is_file():
        # Try viewer_cache subdirectory
        candidate = (VIEWER_CACHE_DIR / filename).resolve()

    try:
        output_root = OUTPUT_DIR.resolve()
    except FileNotFoundError:
        output_root = OUTPUT_DIR

    if not candidate.exists() or not candidate.is_file():
        raise HTTPException(status_code=404, detail="Requested file not found.")

    # Ensure file is within OUTPUT_DIR tree (includes viewer_cache)
    try:
        candidate.relative_to(output_root)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="Invalid filename.") from exc
    return candidate


def _register_viewer_volume(filename: str, display_name: Optional[str] = None) -> str:
    """Load a NIfTI volume from OUTPUT_DIR and return a viewer file_id."""
    _ensure_viewer_available()
    file_path = _resolve_output_path(filename)
    abs_path = file_path.resolve()

    for fid, info in VIEWER_VOLUMES.items():
        if info.get("path") == str(abs_path):
            return fid

    try:
        img = nib.load(str(abs_path))
        data = img.get_fdata(dtype=np.float32)
        affine = np.array(getattr(img, "affine", np.eye(4)), dtype=np.float32)
        header = img.header.copy() if getattr(img, "header", None) is not None else None
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to load NIfTI volume: {exc}")

    fid = str(uuid.uuid4())
    VIEWER_VOLUMES[fid] = {
        "path": str(abs_path),
        "data": data,
        "shape": data.shape,
        "dtype": str(data.dtype),
        "affine": affine,
        "header": header,
        "name": display_name or abs_path.name,
    }
    return fid


def _get_viewer_volume(file_id: str) -> Dict[str, object]:
    """Retrieve cached volume information for a viewer file_id."""
    info = VIEWER_VOLUMES.get(file_id)
    if info is None:
        raise HTTPException(status_code=404, detail="Viewer session not found.")
    return info


def _apply_window(arr: np.ndarray, center: float, width: float, invert: bool) -> np.ndarray:
    """Apply window center/width to numeric array and return uint8 image."""
    try:
        data_min = float(np.nanmin(arr))
        data_max = float(np.nanmax(arr))
    except ValueError:
        data_min = 0.0
        data_max = 0.0

    if width is None or width <= 0:
        width = data_max - data_min

    low = center - width / 2.0
    high = center + width / 2.0

    safe = np.nan_to_num(arr, nan=data_min, posinf=data_max, neginf=data_min)
    safe = np.clip(safe, low, high)

    span = float(high - low)
    if span == 0.0:
        res = np.zeros_like(safe, dtype=np.uint8)
    else:
        scaled = (safe - low) / span
        scaled = np.clip(scaled, 0.0, 1.0)
        res = (scaled * 255.0).round().astype(np.uint8)

    if invert:
        res = 255 - res
    return res


