@app.post("/analyze_bvals")
async def analyze_bvals(
    bval_file: UploadFile = File(..., description="B-values file (.bval)"),
    bvec_file: UploadFile = File(..., description="B-vectors file")
):
    """
    Analyze b-values to show available shells and direction counts.
    This helps users select which shell to process for single-shell analysis.
    """
    try:
        # Read bval file
        bval_content = await bval_file.read()
        bval_text = bval_content.decode('utf-8').strip()
        bvals = np.array([float(x) for x in bval_text.split()])

        # Read bvec file to count directions
        bvec_content = await bvec_file.read()
        bvec_text = bvec_content.decode('utf-8').strip()
        bvec_lines = [line.strip() for line in bvec_text.split('\n') if line.strip()]
        bvecs = np.array([[float(x) for x in line.split()] for line in bvec_lines])

        # Validate
        if bvecs.shape[1] != len(bvals):
            raise HTTPException(
                status_code=400,
                detail=f"Mismatch: {bvecs.shape[1]} bvecs but {len(bvals)} bvals"
            )

        # Identify b0 and diffusion volumes
        b0_mask = bvals < 50
        num_b0 = int(np.sum(b0_mask))

        # Find unique non-b0 b-values (shells)
        diffusion_bvals = bvals[~b0_mask]
        unique_shells = np.unique(diffusion_bvals)

        # Count directions per shell
        shells_info = []
        for shell_bval in unique_shells:
            shell_mask = bvals == shell_bval
            num_directions = int(np.sum(shell_mask))
            shells_info.append({
                "bval": int(shell_bval),
                "num_directions": num_directions,
                "label": f"b={int(shell_bval)} ({num_directions} directions)"
            })

        # Sort by b-value
        shells_info.sort(key=lambda x: x["bval"])

        return {
            "total_volumes": len(bvals),
            "num_b0": num_b0,
            "num_shells": len(shells_info),
            "is_multishell": len(shells_info) > 1,
            "shells": shells_info,
            "all_bvals": bvals.tolist()
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to analyze b-values: {str(e)}")
    finally:
        await bval_file.close()
        await bvec_file.close()


# SimpleITK for image registration (fallback if FSL unavailable)
try:
    import SimpleITK as sitk
    SIMPLEITK_AVAILABLE = True
except ImportError:
    SIMPLEITK_AVAILABLE = False

def check_sitk():
    """Check if SimpleITK is available."""
    return SIMPLEITK_AVAILABLE


# FSL for nonlinear registration (preferred)
# Detect runtime environment: native Linux/WSL vs Windows (needs WSL bridge)
import platform as _platform
_RUNNING_IN_LINUX = _platform.system() == 'Linux'
if _RUNNING_IN_LINUX:
    logging.info("Running natively in Linux/WSL — FSL commands will run directly")
else:
    logging.info("Running on Windows — FSL commands will run via WSL bridge")


def _to_fsl_path(path: Path) -> str:
    """Convert a path to a format FSL can use.

    - On Linux/WSL: resolve and return as-is (already a Linux path)
    - On Windows: convert C:\\Users\\... → /mnt/c/Users/...
    """
    p = str(path.resolve()).replace('\\', '/')
    if not _RUNNING_IN_LINUX and len(p) >= 2 and p[1] == ':':
        drive = p[0].lower()
        return f'/mnt/{drive}{p[2:]}'
    return p


def _run_fsl(cmd: str, timeout: int = 600) -> subprocess.CompletedProcess:
    """Run an FSL command. Uses direct bash on Linux/WSL, or WSL bridge on Windows."""
    if _RUNNING_IN_LINUX:
        full_cmd = ['bash', '-lc', cmd]
    else:
        full_cmd = ['wsl', 'bash', '-lc', cmd]
    logging.info(f"FSL command: {cmd}")
    result = subprocess.run(full_cmd, capture_output=True, text=True, timeout=timeout)
    if result.returncode != 0:
        logging.error(f"FSL command failed (exit {result.returncode}): {result.stderr}")
        raise RuntimeError(f"FSL command failed: {result.stderr.strip()}")
    if result.stdout.strip():
        logging.info(f"FSL output: {result.stdout.strip()}")
    return result


def check_fsl() -> bool:
    """Check if FSL is available (directly on Linux/WSL, or via WSL bridge on Windows)."""
    try:
        if _RUNNING_IN_LINUX:
            full_cmd = ['bash', '-lc', 'which flirt && which fnirt && which applywarp']
        else:
            full_cmd = ['wsl', 'bash', '-lc', 'which flirt && which fnirt && which applywarp']
        result = subprocess.run(full_cmd, capture_output=True, text=True, timeout=10)
        return result.returncode == 0
    except Exception:
        return False


FSL_AVAILABLE = check_fsl()
logging.info(f"FSL: {'available' if FSL_AVAILABLE else 'not available'}")

# Check for FNIRT config (needed for FA registration)
FSL_FNIRT_CONFIG_OK = False
if FSL_AVAILABLE:
    try:
        _fnirt_cfg_cmd = 'test -f ${FSLDIR}/etc/flirtsch/FA_2_FMRIB58_1mm.cnf && echo OK'
        if _RUNNING_IN_LINUX:
            _fnirt_cfg_full = ['bash', '-lc', _fnirt_cfg_cmd]
        else:
            _fnirt_cfg_full = ['wsl', 'bash', '-lc', _fnirt_cfg_cmd]
        result = subprocess.run(_fnirt_cfg_full, capture_output=True, text=True, timeout=10)
        FSL_FNIRT_CONFIG_OK = 'OK' in result.stdout
        if not FSL_FNIRT_CONFIG_OK:
            logging.warning("FSL FNIRT config FA_2_FMRIB58_1mm.cnf not found; FNIRT will fall back to affine")
    except Exception:
        logging.warning("Could not verify FNIRT config availability")

# FMRIB58_FA_1mm template — the correct target for FA_2_FMRIB58_1mm FNIRT config
# Bundled in atlases/ alongside JHU and Harvard-Oxford atlases
FMRIB58_FA_PATH = Path(__file__).parent / 'atlases' / 'FMRIB58_FA_1mm.nii.gz'
if FMRIB58_FA_PATH.exists():
    logging.info(f"FMRIB58_FA_1mm template: {FMRIB58_FA_PATH}")
else:
    logging.warning(f"FMRIB58_FA_1mm not found at {FMRIB58_FA_PATH}; FNIRT will use JHU FA as fallback")
    FMRIB58_FA_PATH = None


