def download_jhu_atlas(force_download: bool = False) -> Dict[str, Path]:
    """
    Download JHU ICBM-DTI-81 atlas files to the project atlases/ directory.

    Parameters:
    -----------
    force_download : bool
        If True, re-download even if files exist

    Returns:
    --------
    dict : Dictionary with paths to 'labels' and 'fa' atlas files
    """
    import urllib.request
    import urllib.error

    ATLAS_DIR.mkdir(parents=True, exist_ok=True)
    atlas_files = {}

    for atlas_type in ['labels', 'fa']:
        filepath = JHU_ATLAS_PATHS[atlas_type]
        atlas_files[atlas_type] = filepath

        if filepath.exists() and not force_download:
            logging.info(f"JHU {atlas_type} atlas already available at {filepath}")
            continue

        # Try primary URL first, then alternative
        urls_to_try = [JHU_ATLAS_URLS[atlas_type], JHU_ATLAS_URLS_ALT[atlas_type]]
        downloaded = False

        for url in urls_to_try:
            try:
                logging.info(f"Downloading JHU {atlas_type} atlas from {url}...")
                urllib.request.urlretrieve(url, filepath)

                # Verify the download is a valid NIfTI
                test_img = nib.load(filepath)
                _ = test_img.shape

                logging.info(f"Successfully downloaded JHU {atlas_type} atlas to {filepath}")
                downloaded = True
                break
            except Exception as e:
                logging.warning(f"Failed to download from {url}: {e}")
                if filepath.exists():
                    filepath.unlink()  # Remove partial download
                continue

        if not downloaded:
            raise Exception(f"Failed to download JHU {atlas_type} atlas from all sources")

    return atlas_files


def download_harvard_oxford_atlas(force_download: bool = False) -> Dict[str, Path]:
    """
    Get Harvard-Oxford cortical and subcortical atlas files from the project atlases/ directory.

    These atlases are bundled with the project, so no download is needed.

    Parameters:
    -----------
    force_download : bool
        Unused, kept for API compatibility

    Returns:
    --------
    dict : Dictionary with paths to 'cortical' and 'subcortical' atlas files
    """
    for atlas_type, filepath in HARVARD_OXFORD_PATHS.items():
        if not filepath.exists():
            raise FileNotFoundError(
                f"Harvard-Oxford {atlas_type} atlas not found at {filepath}. "
                f"Ensure the atlases/ directory contains the bundled atlas files."
            )
        logging.info(f"Harvard-Oxford {atlas_type} atlas available at {filepath}")

    return dict(HARVARD_OXFORD_PATHS)


