@app.get("/sessions/list")
async def list_sessions():
    """List all available processing sessions with metadata.
    Scans root and one level of subdirectories for session_* dirs."""
    try:
        sessions = []
        if not OUTPUT_DIR.exists():
            return {"sessions": [], "folders": []}

        def _collect_sessions(parent: Path, folder_name: str):
            for session_dir in parent.glob("session_*"):
                if not session_dir.is_dir():
                    continue
                metadata_path = session_dir / "metadata.json"
                if not metadata_path.exists():
                    continue
                with open(metadata_path, 'r') as f:
                    metadata = json.load(f)

                processed_dir = session_dir / "processed"
                available_files = {
                    "eigenvalues": (processed_dir / "tensor_eigenvalues.nii.gz").exists(),
                    "eigenvectors": (processed_dir / "tensor_eigenvectors.nii.gz").exists(),
                    "mask": (processed_dir / "mask.nii.gz").exists(),
                    "mean_b0": (processed_dir / "mean_b0.nii.gz").exists(),
                    "eddy_corrected": (processed_dir / "dwi_eddy_corrected.nii.gz").exists(),
                    "denoised": (processed_dir / "dwi_denoised.nii.gz").exists(),
                    "raw": (processed_dir / "dwi_raw.nii.gz").exists()
                }

                sessions.append({
                    "session_id": metadata.get("session_id", session_dir.name),
                    "timestamp": metadata.get("timestamp"),
                    "name": metadata.get("name", f"Session {metadata.get('timestamp', session_dir.name)}"),
                    "description": metadata.get("description", ""),
                    "folder": folder_name,
                    "dir": str(session_dir),
                    "inputs": metadata.get("inputs", {}),
                    "parameters": metadata.get("parameters", {}),
                    "acquisition": metadata.get("acquisition", {}),
                    "available_files": available_files,
                    "alps_results": metadata.get("alps_results")
                })

        # Collect sessions in root
        _collect_sessions(OUTPUT_DIR, "")

        # Collect sessions in subdirectories (one level deep)
        folders = []
        for subfolder in sorted(OUTPUT_DIR.iterdir()):
            if subfolder.is_dir() and not subfolder.name.startswith("session_"):
                folders.append(subfolder.name)
                _collect_sessions(subfolder, subfolder.name)

        # Sort by timestamp desc
        sessions.sort(key=lambda s: s.get("timestamp", ""), reverse=True)

        return {"sessions": sessions, "folders": folders}
    except Exception as e:
        logging.error(f"Error listing sessions: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.delete("/sessions/{session_id}")
async def delete_session(session_id: str):
    """
    Delete a session and all its associated files.

    Parameters:
    - session_id: Session ID (e.g., "session_20251127_224532")

    Returns:
        Success message
    """
    try:
        session_dir = resolve_session_dir(session_id)

        if not session_dir.exists():
            raise HTTPException(status_code=404, detail=f"Session not found: {session_id}")

        # Delete the entire session directory
        import shutil
        shutil.rmtree(session_dir)

        logging.info(f"Deleted session: {session_id}")
        return {"message": f"Session {session_id} deleted successfully"}
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Error deleting session {session_id}: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.put("/sessions/{session_id}")
async def update_session(
    session_id: str,
    name: Optional[str] = None,
    description: Optional[str] = None,
    folder: Optional[str] = None
):
    """
    Update session metadata (name, description, and/or folder).

    Parameters:
    - session_id: Session ID (e.g., "session_20251127_224532")
    - name: New session name (optional)
    - description: New session description (optional)
    - folder: Project folder for organization (optional, empty string = uncategorized)

    Returns:
        Updated session metadata
    """
    try:
        import shutil as _shutil
        session_dir = resolve_session_dir(session_id)

        if not session_dir.exists():
            raise HTTPException(status_code=404, detail=f"Session not found: {session_id}")

        metadata_path = session_dir / "metadata.json"
        if not metadata_path.exists():
            raise HTTPException(status_code=404, detail="Session metadata not found")

        # Load existing metadata
        with open(metadata_path, 'r') as f:
            metadata = json.load(f)

        # Update fields if provided
        if name is not None:
            metadata["name"] = name
        if description is not None:
            metadata["description"] = description
        if folder is not None:
            metadata["folder"] = folder

        # Save updated metadata
        with open(metadata_path, 'w') as f:
            json.dump(metadata, f, indent=2)

        # Physically move session directory if folder changed
        if folder is not None:
            current_parent = session_dir.parent
            if folder:
                target_parent = OUTPUT_DIR / folder
            else:
                target_parent = OUTPUT_DIR
            if current_parent.resolve() != target_parent.resolve():
                target_parent.mkdir(parents=True, exist_ok=True)
                dest = target_parent / session_id
                if not dest.exists():
                    _shutil.move(str(session_dir), str(dest))
                    logging.info(f"Moved session {session_id} to {dest}")
                    # Clean up empty source folder
                    if current_parent != OUTPUT_DIR and current_parent.exists():
                        remaining = [p for p in current_parent.iterdir() if p.is_dir() and p.name.startswith("session_")]
                        if not remaining:
                            current_parent.rmdir()
                            logging.info(f"Removed empty folder directory: {current_parent.name}")

        logging.info(f"Updated session {session_id}: name={name}, description={description}, folder={folder}")
        return {
            "message": "Session updated successfully",
            "session_id": session_id,
            "name": metadata.get("name"),
            "description": metadata.get("description"),
            "folder": metadata.get("folder", "")
        }
    except HTTPException:
        raise
    except Exception as e:
        logging.error(f"Error updating session {session_id}: {e}")
        raise HTTPException(status_code=500, detail=str(e))


class BulkMoveRequest(BaseModel):
    """Request to move multiple sessions into a folder."""
    session_ids: List[str]
    folder: str


@app.post("/sessions/bulk_move")
async def bulk_move_sessions(request: BulkMoveRequest):
    """Move multiple sessions into a folder at once."""
    moved = []
    errors = []
    for sid in request.session_ids:
        session_dir = resolve_session_dir(sid)
        metadata_path = session_dir / "metadata.json"
        if not metadata_path.exists():
            errors.append(f"{sid}: not found")
            continue
        try:
            with open(metadata_path, 'r') as f:
                metadata = json.load(f)
            metadata["folder"] = request.folder
            with open(metadata_path, 'w') as f:
                json.dump(metadata, f, indent=2)
            moved.append(sid)
        except Exception as e:
            errors.append(f"{sid}: {e}")

    return {"moved": len(moved), "errors": errors}


