def main() -> None:
    """Console entry point: `dti-alps`."""
    import os
    port = int(os.environ.get("PORT", "8080"))
    print(f"DTI-ALPS server starting on http://0.0.0.0:{port}")
    print(f"  API docs: http://0.0.0.0:{port}/docs")
    uvicorn.run(
        "dti_alps_refined.server:app",
        host="0.0.0.0",
        port=port,
        reload=False,
        log_level="info",
    )


if __name__ == "__main__":
    main()
